<script setup>
import AppNavBar from '../../components/AppNavBar.vue'
import FlowRibbon from '../../components/FlowRibbon.vue'
import { computed, ref } from 'vue'
import { onLoad, onShow, onUnload } from '@dcloudio/uni-app'
import { backHome } from '../../utils/profile.js'
import { orderStatus } from '../../utils/orders.js'
import { canOrderAction, currentAfterSale, afterSales, batchItems } from '../../utils/order-actions.js'
import { mealToRoute } from '../../utils/meal-flow.js'
import { service } from '../../services/index.js'
import { storageContext as storageScope } from '../../services/storage.js'
const orderId=ref(''),order=ref(null),loading=ref(false),busy=ref(false),error=ref(''),modalBusy=ref(false)
const logisticsOpen=ref(false),batchesOpen=ref(false),requestedMode=ref(''),selectedBatchIndex=ref(1)
const addressOpen=ref(false),addresses=ref([]),serviceOpen=ref(false),resumeOpen=ref(false),resumePreview=ref(null)
const serviceForm=ref(null),drafts=new Map()
let loadVersion=0,disposed=false
const hasBatches=computed(()=>Boolean(order.value?.deliveryBatches?.length))
const selectedBatch=computed(()=>order.value?.deliveryBatches?.find(batch=>batch.index===selectedBatchIndex.value))
const receivedBatchIndices=computed(()=>order.value?.receivedBatchIndices?.length?order.value.receivedBatchIndices:order.value?.sourcePlanId&&order.value?.status==='delivered'?[1]:[])
const delivered=computed(()=>hasBatches.value?receivedBatchIndices.value.includes(selectedBatchIndex.value):order.value?.status==='delivered')
const status=computed(()=>{
 if(!order.value)return orderStatus(null)
 if(order.value.planPaused||['pending','paused','refund_pending','cancelled'].includes(order.value.status))return orderStatus(order.value)
 if(hasBatches.value)return delivered.value?{label:'本批已送达',detail:'本批食材已确认收到'}:selectedBatch.value?.fulfillmentStatus==='shipped'?{label:'本批配送中',detail:'请查看配送进度'}:{label:'本批待配送',detail:'等待配送与收货确认'}
 return orderStatus(order.value)
})
const goods=computed(()=>order.value?batchItems(order.value,selectedBatchIndex.value):[])
const total=computed(()=>order.value?(order.value.totalCents/100).toFixed(2):'0.00')
const deliveryInfo=computed(()=>selectedBatch.value?.addressSnapshot||order.value?.addressSnapshot)
const existingService=computed(()=>order.value?currentAfterSale(order.value,hasBatches.value?selectedBatchIndex.value:null):null)
const serviceHistory=computed(()=>order.value?afterSales(order.value).filter(entry=>entry.batchIndex===(hasBatches.value?selectedBatchIndex.value:null)):[])
const paymentConfirmed=computed(()=>order.value?.paymentStatus?order.value.paymentStatus==='paid':order.value&&!['pending','cancelled'].includes(order.value.status))
const preparing=computed(()=>paymentConfirmed.value&&!['cancelled','refund_pending'].includes(order.value?.status)&&!order.value?.planPaused&&['preparing','shipped','partial','delivered'].includes(selectedBatch.value?.fulfillmentStatus||order.value?.fulfillmentStatus||'preparing'))
const cookingMeals=computed(()=>selectedBatch.value?.meals||order.value?.cookingGuides?.[0]?.guides.map(g=>({type:g.meal,name:g.dishes.join('、')}))||(order.value?.cookingGuide?[{type:order.value.cookingGuide.meal,name:order.value.cookingGuide.dishes.join('、')}]:[]))
function allowed(action){return canOrderAction(order.value,action,selectedBatchIndex.value)}
onLoad(options=>{orderId.value=options.id||'';requestedMode.value=options.mode||'';logisticsOpen.value=options.mode==='logistics';selectedBatchIndex.value=Math.max(1,Number(options.batch)||1)})
onShow(loadOrder)
onUnload(()=>{disposed=true;loadVersion++})
async function loadOrder(){
 const version=++loadVersion,scope=storageScope();loading.value=true;error.value=''
 try{const next=await service.order(orderId.value);if(disposed||version!==loadVersion||scope!==storageScope())return;order.value=next;if(hasBatches.value&&!selectedBatch.value)selectedBatchIndex.value=1;if(requestedMode.value==='service'){requestedMode.value='';requestAfterSale()}}
 catch(e){if(!disposed&&version===loadVersion&&scope===storageScope())error.value=e.message||'读取失败，请重试'}
 finally{if(version===loadVersion)loading.value=false}
}
async function runAction(action,work,index=selectedBatchIndex.value){
 if(busy.value)return false
 if(!canOrderAction(order.value,action,index)){error.value='当前状态不支持此操作，请刷新订单';return false}
 loadVersion++;loading.value=false;busy.value=true;error.value='';const scope=storageScope()
 try{const next=await work();if(disposed||scope!==storageScope())return false;if(next?.id)order.value=next;return true}
 catch(e){if(!disposed&&scope===storageScope())error.value=e.message||'操作未完成，请重试';return false}
 finally{busy.value=false}
}
function confirmAction(title,content,action,work,confirmText='确认提交'){
 if(busy.value||modalBusy.value||!allowed(action))return
 const index=selectedBatchIndex.value;modalBusy.value=true
 uni.showModal({title,content,confirmText,success:async({confirm})=>{modalBusy.value=false;if(confirm)return runAction(action,work,index)},fail:()=>{modalBusy.value=false;error.value='确认窗口未能打开，请重试';uni.showToast({title:title==='确认收到食材？'?'收货确认窗口未能打开，请重试':error.value,icon:'none'})}})
}
function confirmReceived(){const index=selectedBatchIndex.value;confirmAction('确认收到食材？',hasBatches.value?'只确认当前第 '+index+' 批；其他批次及暂停、退款状态保持不变。':'确认已经收到食材。测试操作不会产生真实配送。','receive',()=>service.receive(orderId.value,index),'确认收到')}
function selectBatch(index){if(busy.value||modalBusy.value)return;selectedBatchIndex.value=index;batchesOpen.value=false;serviceOpen.value=false;addressOpen.value=false;error.value=''}
function requestAfterSale(){
 if(busy.value||!allowed('afterSale'))return
 const key=hasBatches.value?selectedBatchIndex.value:'ordinary'
 if(!drafts.has(key))drafts.set(key,{batchIndex:hasBatches.value?selectedBatchIndex.value:null,items:goods.value.map(item=>({id:item.id,name:item.name,quantity:0,max:item.quantity})),expectation:'希望补发',reason:'商品问题',description:'',attachments:[]})
 serviceForm.value=drafts.get(key);serviceOpen.value=true;error.value=''
}
async function submitAfterSale(){if(!serviceForm.value)return;const form=JSON.parse(JSON.stringify(serviceForm.value));const ok=await runAction('afterSale',()=>service.submitAfterSale(orderId.value,form));if(ok)uni.showToast({title:'测试申请已记录',icon:'success'})}
function chooseEvidence(){
 if(busy.value)return;const form=serviceForm.value,scope=storageScope();if(form.attachments.length>=3)return
 uni.chooseImage({count:3-form.attachments.length,sourceType:['album','camera'],success:r=>{if(!disposed&&scope===storageScope())form.attachments.push(...r.tempFilePaths.slice(0,3-form.attachments.length))},fail:()=>{error.value='未选择凭证，可重试或继续填写说明'}})
}
async function togglePause(){
 if(order.value?.planPaused||order.value?.status==='paused'){
   const ok=await runAction('resume',async()=>{resumePreview.value=await service.resumePreview(orderId.value)});if(ok)resumeOpen.value=true
 }else confirmAction('暂停剩余计划？','只暂停可变更的未发货批次，已发货和已收货批次保持不变。','pause',()=>service.pausePlan(orderId.value),'确认暂停')
}
async function confirmResume(){const ok=await runAction('resume',()=>service.resumePlan(orderId.value,resumePreview.value));if(ok)resumeOpen.value=false}
async function cancelRemaining(){
 let preview;const ok=await runAction('cancelRemaining',async()=>{preview=await service.refundPreview(orderId.value)})
 if(ok)confirmAction('取消剩余计划','可申请取消 '+preview.batchIndices.length+' 批。'+(preview.amountCents===null?preview.explanation:'预计退款 ¥'+(preview.amountCents/100).toFixed(2)),'cancelRemaining',()=>service.cancelRemaining(orderId.value),'提交申请')
}
async function changeBatchAddress(){const ok=await runAction('changeAddress',async()=>{addresses.value=await service.addresses()});if(ok)addressOpen.value=true}
async function selectAddress(address){const index=selectedBatchIndex.value;const ok=await runAction('changeAddress',()=>service.changeBatchAddress(orderId.value,index,address),index);if(ok){addressOpen.value=false;uni.showToast({title:'当前批次地址已更新',icon:'success'})}}
function reorder(){uni.navigateTo({url:'/pages/shop/index?meal='+mealToRoute(order.value.meal)+'&reorder='+encodeURIComponent(order.value.id)})}
function cook(meal){if(delivered.value)uni.navigateTo({url:'/pages/cook/index?id='+encodeURIComponent(order.value.id)+'&meal='+mealToRoute(meal)+(hasBatches.value?'&batch='+selectedBatchIndex.value:'')})}
function nutritionist(){uni.reLaunch({url:'/pages/chat/index'})}
</script>
<template>
<view class="screen detail-screen">
<AppNavBar><view class="nav-row"><button class="icon-button" @click="backHome">‹</button><text class="nav-title">订单详情</text><text class="pill">测试数据</text></view></AppNavBar>
<text v-if="loading" class="safe-note">正在读取订单…</text>
<view v-if="error" class="error-panel"><text class="inline-error">{{error}}</text><button v-if="!busy" @click="loadOrder">刷新订单</button></view>
<view v-if="!loading&&!order&&!error" class="card info-card"><text>订单不存在或当前账号无权查看。</text><button @click="backHome">返回</button></view>
<template v-if="order">
<FlowRibbon :current="paymentConfirmed?4:3" class="detail-flow"/>
<view class="status-hero" :class="{delivered}"><view><text class="display-title">{{status.label}}</text><text>{{status.detail}}</text></view><view class="status-mark">{{delivered?'✓':'···'}}</view></view>
<view class="progress-card card"><view class="progress-head"><text class="section-title">配送进度</text><button @click="logisticsOpen=true">查看物流 ›</button></view><view class="progress-track"><view :class="{active:paymentConfirmed}"><text>1</text><text>{{paymentConfirmed?'已支付':'待支付确认'}}</text></view><view :class="{active:preparing}"></view><view :class="{active:preparing}"><text>2</text><text>{{order.planPaused?'计划暂停':selectedBatch?.fulfillmentStatus==='shipped'?'配送中':paymentConfirmed?'商家备货':'等待备货'}}</text></view><view :class="{active:delivered}"></view><view :class="{active:delivered}"><text>3</text><text>已送达</text></view></view></view>
<view v-if="hasBatches&&selectedBatch" class="card batches-card"><view class="progress-head"><view><text class="section-title">计划配送批次</text><text>已收 {{receivedBatchIndices.length}} / {{order.deliveryBatches.length}} 批</text></view><button :disabled="busy" @click="batchesOpen=true">切换批次 ›</button></view><view class="selected-batch"><text>当前第 {{selectedBatch.index}} 批 · {{selectedBatch.date}}</text><text>{{selectedBatch.dishes?.join('、')}}</text></view></view>
<view class="card goods-card"><view class="card-title"><text class="section-title">{{hasBatches?'当前批次商品':'商品清单'}}</text></view><view v-for="item in goods" :key="item.id" class="goods-row"><view class="goods-icon">{{item.icon}}</view><view><text>{{item.name}}</text><text>{{item.pack}}{{item.unit}}/包 × {{item.quantity}}</text></view><text>¥{{(item.priceCents*item.quantity/100).toFixed(2)}}</text></view><view class="total-row"><text>整单金额（测试）</text><text>¥{{total}}</text></view></view>
<view class="card info-card"><text class="section-title">{{hasBatches?'本批配送信息':'配送信息'}}</text><template v-if="deliveryInfo"><text>{{deliveryInfo.name}} · {{deliveryInfo.phone}}</text><text>{{deliveryInfo.region}} {{deliveryInfo.detail}}</text></template><template v-else><text>{{order.contact}}</text><text>{{order.address}}</text></template><text>订单编号：{{order.id}}</text><text>下单时间：{{order.displayTime}}</text></view>
<view v-if="serviceHistory.length" class="after-sale-note"><text>本批售后记录</text><text v-for="entry in serviceHistory" :key="entry.id">{{entry.status}} · {{entry.reason}} · {{entry.expectation}}</text><button @click="requestAfterSale">查看详情</button></view>
<view v-if="hasBatches" class="plan-actions card"><text class="section-title">计划管理</text><view><button v-if="allowed('pause')||allowed('resume')" :disabled="busy||modalBusy" @click="togglePause">{{order.planPaused||order.status==='paused'?'预览恢复排程':'暂停未发货批次'}}</button><button v-if="allowed('changeAddress')" :disabled="busy||modalBusy" @click="changeBatchAddress">修改当前批次地址</button><button v-if="allowed('cancelRemaining')" :disabled="busy||modalBusy" class="danger" @click="cancelRemaining">取消剩余计划／退款预览</button></view></view>
<view class="service-actions"><button @click="logisticsOpen=true">查看物流</button><button v-if="allowed('afterSale')" :disabled="busy" @click="requestAfterSale">{{existingService?'查看售后':'申请售后'}}</button><button :disabled="busy" @click="reorder">再买一单</button></view>
<button v-if="allowed('receive')" class="primary-button receive-button" :disabled="busy||modalBusy" @click="confirmReceived">{{busy?'正在提交…':hasBatches?'确认已收到第'+selectedBatchIndex+'批食材':'确认已收到食材'}}</button>
<view v-if="delivered" class="card cooking-meals"><view v-for="meal in cookingMeals" :key="meal.type"><view><text>{{meal.type}}</text><text>{{meal.name}}</text></view><button class="primary-button" @click="cook(meal.type)">开始做饭</button></view></view>
<button class="secondary-button" @click="nutritionist">返回营养师</button>
<view v-if="logisticsOpen" class="sheet-mask"><view class="sheet"><view class="sheet-head"><text class="section-title">配送进度</text><button @click="logisticsOpen=false">×</button></view><text>{{status.label}} · {{status.detail}}</text><text class="demo-label">测试订单没有真实骑手或物流轨迹。</text><button class="primary-button" @click="logisticsOpen=false">关闭</button></view></view>
<view v-if="batchesOpen" class="sheet-mask"><view class="sheet"><view class="sheet-head"><text class="section-title">选择批次</text><button @click="batchesOpen=false">×</button></view><scroll-view scroll-y class="batch-scroll"><button v-for="batch in order.deliveryBatches" :key="batch.batchId||batch.index" class="sheet-batch" @click="selectBatch(batch.index)"><text>第{{batch.index}}批</text><view><text>{{batch.date}}</text><text>{{receivedBatchIndices.includes(batch.index)?'已收到':batch.fulfillmentStatus==='paused'?'已暂停':batch.fulfillmentStatus==='shipped'?'配送中':'待配送'}}</text></view><text>›</text></button></scroll-view></view></view>
<view v-if="addressOpen" class="sheet-mask"><view class="sheet"><view class="sheet-head"><text class="section-title">第{{selectedBatchIndex}}批配送地址</text><button :disabled="busy" @click="addressOpen=false">×</button></view><scroll-view scroll-y class="batch-scroll"><button v-for="address in addresses" :key="address.id" class="address-option" :disabled="busy" @click="selectAddress(address)"><text>{{address.name}} · {{address.phone}}</text><text>{{address.region}} {{address.detail}}</text></button><text v-if="!addresses.length">还没有地址，请先新增收货地址。</text></scroll-view><text v-if="error" class="inline-error">{{error}}</text><button :disabled="busy" class="secondary-button" @click="uni.navigateTo({url:'/pages/address/edit'});addressOpen=false">新增地址</button><text class="demo-label">仅更新当前可变更批次，整单原始快照和其他批次保持不变。</text></view></view>
<view v-if="resumeOpen&&resumePreview" class="sheet-mask"><view class="sheet"><view class="sheet-head"><text class="section-title">核对恢复排程</text><button :disabled="busy" @click="resumeOpen=false">×</button></view><scroll-view scroll-y class="batch-scroll"><text v-for="batch in resumePreview.batches" :key="batch.index" class="schedule-row">第{{batch.index}}批 · {{batch.date}}</text></scroll-view><text class="demo-label">这是测试排程，实际运力及可预约日期由商城提供。</text><text v-if="error" class="inline-error">{{error}}</text><button class="primary-button" :disabled="busy" @click="confirmResume">{{busy?'正在恢复…':'确认恢复'}}</button></view></view>
<view v-if="serviceOpen&&serviceForm" class="sheet-mask"><view class="sheet after-sale-sheet"><view class="sheet-head"><text class="section-title">{{existingService?'售后详情':'申请售后'}}{{hasBatches?' · 第'+selectedBatchIndex+'批':''}}</text><button :disabled="busy" @click="serviceOpen=false">×</button></view>
<scroll-view scroll-y class="service-scroll"><template v-if="existingService"><text class="schedule-row">工单：{{existingService.id||'历史申请'}}</text><text class="schedule-row">状态：{{existingService.status}}</text><text class="schedule-row">{{existingService.reason}} · {{existingService.expectation}}</text><text class="schedule-row">{{existingService.description}}</text><text v-for="item in existingService.items" :key="item.id" class="schedule-row">{{item.name}} × {{item.quantity}}</text><image v-for="path in existingService.attachments" :key="path" :src="path" class="evidence" mode="aspectFill"/><text class="demo-label">已有处理中申请，请勿重复提交。测试申请不产生真实退款或补发。</text></template>
<template v-else><text class="form-label">选择商品和申请数量（0 表示不申请）</text><view v-for="item in serviceForm.items" :key="item.id" class="service-product"><text>{{item.name}} · 最多{{item.max}}</text><input v-model="item.quantity" type="number" class="field-input" :disabled="busy"/></view><text class="form-label">期望处理</text><picker :range="['希望补发','希望退款','请工作人员联系我']" :disabled="busy" @change="serviceForm.expectation=['希望补发','希望退款','请工作人员联系我'][$event.detail.value]"><view class="field-input">{{serviceForm.expectation}}</view></picker><text class="form-label">问题类型</text><picker :range="['商品问题','少件／漏件','配送问题']" :disabled="busy" @change="serviceForm.reason=['商品问题','少件／漏件','配送问题'][$event.detail.value]"><view class="field-input">{{serviceForm.reason}}</view></picker><text class="form-label">补充说明</text><textarea v-model="serviceForm.description" :disabled="busy" class="text-area" maxlength="500" placeholder="描述问题，提交失败会保留填写内容"/><text class="form-label">凭证图片（最多 3 张）</text><view><view v-for="(path,index) in serviceForm.attachments" :key="path" class="evidence-wrap"><image :src="path" class="evidence" mode="aspectFill"/><button :disabled="busy" @click="serviceForm.attachments.splice(index,1)">移除</button></view></view><button :disabled="busy||serviceForm.attachments.length>=3" class="secondary-button" @click="chooseEvidence">添加凭证</button><text class="demo-label">凭证仅在本机预览；测试申请不会上传或创建真实工单。</text></template></scroll-view>
<text v-if="error" class="inline-error">{{error}}</text><button v-if="!existingService" class="primary-button" :disabled="busy" @click="submitAfterSale">{{busy?'正在提交…':'提交申请'}}</button></view></view>
</template></view>
</template>
<style scoped>
.error-panel{padding:24rpx;margin:20rpx 0;background:#fff2ee;border-radius:20rpx}.error-panel button{color:#246b50;min-height:80rpx}.address-option{width:100%;text-align:left;padding:20rpx;display:flex;flex-direction:column;gap:12rpx;border-bottom:1rpx solid #e5e5ea;font-size:27rpx}.schedule-row{display:block;padding:16rpx 0;font-size:27rpx}.service-scroll{max-height:55vh;margin:24rpx 0}.service-product{display:flex;align-items:center;gap:20rpx;padding:16rpx 0;font-size:25rpx}.service-product>text{flex:1}.service-product input{width:140rpx}.evidence{width:150rpx;height:150rpx;border-radius:16rpx}.evidence-wrap{display:inline-flex;flex-direction:column;gap:8rpx;margin:12rpx}.sheet>text{display:block;margin:16rpx 0}

.cooking-meals{padding:24rpx;margin:24rpx 0}.cooking-meals>view{display:flex;justify-content:space-between;gap:18rpx;align-items:center;padding:20rpx 0;border-bottom:1rpx solid #dce5d5}.cooking-meals>view>view{flex:1;display:flex;flex-direction:column;gap:10rpx;font-size:23rpx}.cooking-meals .primary-button{min-height:70rpx;font-size:22rpx;padding:0 18rpx}
.detail-screen { padding-bottom: 70rpx; }.detail-flow { margin-top: 20rpx; }.status-hero { display: flex; align-items: center; justify-content: space-between; margin-top: 34rpx; padding: 30rpx; border-radius: 34rpx; background: #246b50; color: white; box-shadow: 0 20rpx 40rpx rgba(31,107,82,.17); }.status-hero.delivered { background: #315f4f; }.status-hero > view:first-child { display: flex; flex-direction: column; gap: 9rpx; }.status-hero .eyebrow { color: #e0eee5; }.status-hero .display-title { font-size: 46rpx; }.status-hero > view:first-child > text:last-child { color: #d6e5d9; font-size: 20rpx; }.status-mark { width: 76rpx; height: 76rpx; display: flex; align-items: center; justify-content: center; border-radius: 26rpx 26rpx 9rpx; background: #e9ecea; color: #1d1d1f; font-size: 34rpx; font-weight: 900; }
.progress-card,.goods-card,.info-card,.batches-card { margin-top: 22rpx; padding: 26rpx; }.progress-head,.card-title { display: flex; align-items: center; justify-content: space-between; }.progress-head > view { display: flex; flex-direction: column; gap: 7rpx; }.progress-head > view > text:last-child { color: #75867e; font-size: 18rpx; }.progress-head button { color: #246b50; font-size: 20rpx; font-weight: 800; }.card-title > text:last-child { color: #7a8982; font-size: 19rpx; }
.progress-track { display: grid; grid-template-columns: 1fr 44rpx 1fr 44rpx 1fr; align-items: start; margin-top: 25rpx; }.progress-track > view:nth-child(even) { height: 3rpx; margin-top: 23rpx; background: #d9e1d7; }.progress-track > view:nth-child(even).active { background: #246b50; }.progress-track > view:nth-child(odd) { display: flex; flex-direction: column; align-items: center; gap: 8rpx; color: #8a9891; font-size: 17rpx; text-align: center; }.progress-track > view:nth-child(odd) text:first-child { width: 46rpx; height: 46rpx; display: flex; align-items: center; justify-content: center; border-radius: 50%; background: #e3e9df; color: #74857d; font-weight: 800; }.progress-track > view:nth-child(odd).active { color: #246b50; font-weight: 800; }.progress-track > view:nth-child(odd).active text:first-child { background: #246b50; color: white; }.progress-note { display: block; margin-top: 22rpx; padding: 17rpx; border-radius: 17rpx; background: #eef2df; color: #5e7469; font-size: 19rpx; line-height: 1.55; }
